import { test, expect } from "@playwright/test";

test("imports unique rows and exports the complete filtered set", async ({ page }) => {
  await page.goto("/inventory"); await page.getByLabel("CSV file").setInputFiles({ name: "items.csv", mimeType: "text/csv", buffer: Buffer.from('sku,name,quantity\nA1,"Widget, large",4\nA1,duplicate,2') });
  await expect(page.getByText(/row 3.*duplicate/i)).toBeVisible(); await page.getByRole("button", { name: "Confirm import" }).click(); const download = page.waitForEvent("download"); await page.getByRole("button", { name: "Export filtered CSV" }).click(); expect((await download).suggestedFilename()).toMatch(/csv$/);
});
